#!/usr/bin/env python3
"""Generate the real-drv fixture for template_graph tests.

Run from the project root::

    python3 template_graph/tests/fixtures/generate.py

Produces ONE root .drv path that bundles:

  sum-root .drv
    ├── toolchains .drv        ← inputDrvs = 8 cc-wrappers
    └── matrix-hello .drv      ← inputDrvs = 16 hello variants

The root path is written to ``hello_sum_drv.txt`` (single line).
Test code reads that one path, walks ``inputDrvs`` to find the
toolchains wrapper plus N matrix wrappers, and from each reads the
toolchain / variant lists.

Toolchains live in their own (binary-independent) wrapper because
they are shared across every matrix. Adding more binaries means
adding more ``matrix-<binary>`` entries to the call below.

This script is a thin caller over ``template_graph.make_sum_drv``
(the reusable tool for building sum drvs from any toolchain list
plus any number of matrices).
"""

from __future__ import annotations

import sys
from pathlib import Path

# Make the template_graph package importable when running this file
# directly from the project root.
PROJECT_ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(PROJECT_ROOT))

from template_graph.make_sum_drv import make_sum_drv  # noqa: E402


SYS = "x86_64-linux"
PKG = "hello"
ARCHS = ["x86_64", "aarch64", "armv7l-hf", "riscv64"]
COMPILERS = ["gcc15", "clang21"]
SUFFIXES = [
    "gcc15-O0-baseline-default-san-off-march-default",
    "gcc15-O2-baseline-default-san-off-march-default",
    "clang21-O0-baseline-default-san-off-march-default",
    "clang21-O2-baseline-default-san-off-march-default",
]

FIX_DIR = Path(__file__).parent
OUT_FILE = FIX_DIR / "hello_sum_drv.txt"


def _toolchain_attrs() -> list[str]:
    return [
        f'outputs._crossToolchainMap.{SYS}.{arch}."{comp}"'
        for arch in ARCHS
        for comp in COMPILERS
    ]


def _variant_attrs() -> list[str]:
    return [
        f'outputs.dataset.{SYS}.{PKG}.{arch}."{suffix}"'
        for arch in ARCHS
        for suffix in SUFFIXES
    ]


def main() -> int:
    flake_ref = f"git+file://{PROJECT_ROOT}"
    bash_attr = f"inputs.nixpkgs.legacyPackages.{SYS}.bash"
    drv = make_sum_drv(
        flake_ref=flake_ref,
        bash_attr=bash_attr,
        toolchain_attrs=_toolchain_attrs(),
        matrices={f"matrix-{PKG}": _variant_attrs()},
        root_name="sum-root",
        toolchains_name="toolchains",
        system=SYS,
    )
    OUT_FILE.write_text(
        f"# Generated by template_graph/tests/fixtures/generate.py\n"
        f"# Root sum-drv bundling {len(_toolchain_attrs())} toolchains "
        f"+ {len(_variant_attrs())} {PKG} variants.\n"
        f"{drv}\n"
    )
    print(f"wrote {OUT_FILE}", file=sys.stderr)
    print(drv)
    return 0


if __name__ == "__main__":
    sys.exit(main())
